const materials={POLISHED_DEEPSLATE:['拋光深板岩','#57616c'],BLAST_FURNACE:['高爐','#797e82'],CRAFTER:['合成器','#ad805b'],PISTON:['活塞','#b7a074'],WAXED_CHISELED_COPPER:['上蠟浮雕銅方塊','#bf7955'],WAXED_COPPER_BLOCK:['上蠟銅方塊','#cf9066'],WAXED_CUT_COPPER_STAIRS:['上蠟切製銅階梯','#d5a077'],POLISHED_DEEPSLATE_STAIRS:['拋光深板岩階梯','#75808b'],LODESTONE:['磁石','#99a6ae'],POLISHED_ANDESITE:['拋光安山岩','#adb1ac'],HOPPER:['漏斗','#56636a'],GRINDSTONE:['砂輪','#b5a990'],CAULDRON:['鍋釜','#596270'],POLISHED_ANDESITE_STAIRS:['拋光安山岩階梯','#c2c5be'],SMITHING_TABLE:['鍛造台','#765a4e'],STONE_PRESSURE_PLATE:['石製壓力板','#aaa99c'],BREWING_STAND:['釀造台','#b99f56']};
function material(t,d,y,s){if(t==='THERMAL_FOUNDRY'||t==='ASSEMBLY_ARRAY'){if(y===0)return'POLISHED_DEEPSLATE';if(y===1){if(d===0&&s===0)return t==='THERMAL_FOUNDRY'?'BLAST_FURNACE':'CRAFTER';if(t==='ASSEMBLY_ARRAY'&&d===0&&s!==0)return'PISTON';if(d===2&&s===0)return'WAXED_CHISELED_COPPER';return'WAXED_COPPER_BLOCK'}return((s!==0&&d<2)||(s===0&&(d===0||d===2)))?'WAXED_CUT_COPPER_STAIRS':'WAXED_COPPER_BLOCK'}const stone=t==='STONE_PRESS'||t==='ADVANCED_SOLIDIFIER';if(y===0){if(s!==0)return d===0?'POLISHED_DEEPSLATE_STAIRS':d===1?'POLISHED_DEEPSLATE':null;return d===0?'LODESTONE':d===1?(stone?'POLISHED_DEEPSLATE':'POLISHED_ANDESITE'):'POLISHED_DEEPSLATE'}if(y===1){if(s!==0)return d===0?'HOPPER':d===1?'POLISHED_ANDESITE':null;if(d===0)return t==='PROCESSING_TOWER'?'CRAFTER':t==='STONE_PRESS'?'GRINDSTONE':'CAULDRON';return'POLISHED_ANDESITE'}if(s!==0)return d===1?'POLISHED_ANDESITE_STAIRS':null;return d===0?(stone?'PISTON':'POLISHED_ANDESITE_STAIRS'):d===1?'POLISHED_ANDESITE':'POLISHED_ANDESITE_STAIRS'}
