function stairState(b){if(!b.m.endsWith('_STAIRS'))return null;const facing=b.y===0?'south':b.x<0?'east':b.x>0?'west':b.z===0?'south':'north';const corner=b.m==='WAXED_CUT_COPPER_STAIRS'&&b.z===0&&b.x!==0;return {facing,shape:corner?(b.x<0?'outer_right':'outer_left'):'straight'}}
