function directionText(b){const t=stairState(b);if(t)return '下半階梯・高側朝'+({north:'正面',south:'背面',east:'右方',west:'左方'}[t.facing])+(t.shape!=='straight'?'・外轉角':'');switch(b.m){case 'PISTON':return '活塞木面朝'+(b.y===2?'下方':b.x<0?'右方（中心）':'左方（中心）')+'・未伸出';case 'HOPPER':return '大口朝上・細管朝下';case 'CRAFTER':return '輸出孔朝正面・九宮格朝上';case 'GRINDSTONE':return '地面式・支腳朝下・朝正面';case 'BLAST_FURNACE':return '爐口朝正面・頂面朝上';case 'STONE_PRESSURE_PLATE':return '水平放置・貼下方鍛造台頂面';case 'BREWING_STAND':return '直立放置・底座朝下';case 'CAULDRON':return '鍋口朝上';case 'SMITHING_TABLE':return '工具工作面朝上・無朝向屬性';default:return '無朝向屬性・依格位放置'}}
function setup(){model=structures[+$('structure-select').value];blocks=[];if(model[2])model[2].forEach((m,y)=>blocks.push({x:0,y,z:0,m,core:y===1}));else for(let y=0;y<3;y++)for(let z=0;z<3;z++)for(let x=-1;x<=1;x++){const m=material(model[1],z,y,x);if(m)blocks.push({x,y,z,m,core:y===1&&z===0&&x===0})}keys=[...new Set(blocks.map(b=>b.m))];layer=0;selected=null;$('layer-select').innerHTML=Array.from({length:model[2]?2:3},(_,i)=>`<option value="${i}">第 ${i+1} 層${i===0?'・底層':''}</option>`).join('');$('model-title').textContent=model[0];$('activate-help').textContent=model[3];$('materials-list').innerHTML=keys.map((m,i)=>`<li><span class="mat-dot" style="background:${materials[m][1]}">${i+1}</span><span>${materials[m][0]}</span><b>× ${blocks.filter(b=>b.m===m).length}</b></li>`).join('');update()}
function inspect(b){selected=b;$('block-inspect').textContent=`${materials[b.m][0]}｜第 ${b.y+1} 層・${model[2]?'中央':(b.z===0?'前排':b.z===1?'中排':'後排')+'・'+(b.x===0?'中央':b.x<0?'左側':'右側')}${b.core?'｜啟用核心':''}${directionText(b)?'｜'+directionText(b):''}`;draw()}
function update(){layer=+$('layer-select').value;$('layer-title').textContent=`第 ${layer+1} 層${layer===0?'・先蓋底座':''}`;$('prev-layer').disabled=layer===0;$('next-layer').disabled=layer===(model[2]?1:2);const cells=[];for(let z=model[2]?0:2;z>=0;z--)for(let x=model[2]?0:-1;x<=(model[2]?0:1);x++){const b=blocks.find(b=>b.x===x&&b.z===z&&b.y===layer);cells.push(b?`<button class="grid-block ${b.core?'core-cell':''}" data-x="${x}" data-z="${z}"><span class="mat-dot" style="background:${materials[b.m][1]}">${keys.indexOf(b.m)+1}</span>${materials[b.m][0]}${b.core?'<strong>★ 啟用核心</strong>':''}${directionText(b)?'<small>'+directionText(b)+'</small>':''}</button>`:'<div class="grid-air">留空<br><small>不要放方塊</small></div>')}$('layer-grid').style.gridTemplateColumns=model[2]?'1fr':'repeat(3,minmax(0,1fr))';$('layer-grid').innerHTML=cells.join('');$('layer-grid').querySelectorAll('button').forEach(b=>b.onclick=()=>inspect(blocks.find(v=>v.x===+b.dataset.x&&v.z===+b.dataset.z&&v.y===layer)));$('layer-help').textContent=layer===0?'先依格位表放好底層，再按「下一層」。':layer===(model[2]?1:2)?'這是最後一層。完成後切換「蓋到這一層」檢查全貌，再啟用设备。'.replace('设备','設備'):'接著在底層正上方放置這一層，金色格子是啟用核心。';draw()}
function project(x,y,z,w,h){const a=x*Math.cos(yaw)-z*Math.sin(yaw),d=x*Math.sin(yaw)+z*Math.cos(yaw),v=y*Math.cos(pitch)+d*Math.sin(pitch),depth=-y*Math.sin(pitch)+d*Math.cos(pitch);let unit=Math.min(w/6,h/6)*zoom;return{x:w/2+a*unit,y:h*.57-v*unit,depth}}
const textureImages={};let loadedTextures=0,textureErrors=0;const texturePaths=[...new Set(Object.values(window.TEA_BLOCK_MODELS).flatMap(m=>m.elements.flatMap(e=>Object.values(e.faces).map(f=>f.texture))))];texturePaths.forEach(t=>{const im=new Image();textureImages[t]=im;im.onload=()=>{loadedTextures++;draw()};im.onerror=()=>{textureErrors++;$('block-inspect').textContent='部分遊戲材質載入失敗，請重新整理。';draw()};im.src='/assets/careers/textures/'+t.replaceAll('/','_')+'.png'});
function rot(v,axis,degrees,origin=[8,8,8]){const a=degrees*Math.PI/180,c=Math.cos(a),s=Math.sin(a),q=v.map((n,i)=>n-origin[i]);const [i,j]=axis==='x'?[1,2]:axis==='y'?[2,0]:[0,1];const first=q[i];q[i]=first*c-q[j]*s;q[j]=first*s+q[j]*c;return q.map((n,i)=>n+origin[i])}
function draw(){const w=canvas.clientWidth,h=canvas.clientHeight;if(!w||!h)return;const ratio=window.devicePixelRatio||1;if(canvas.width!==Math.round(w*ratio)||canvas.height!==Math.round(h*ratio)){canvas.width=Math.round(w*ratio);canvas.height=Math.round(h*ratio)}ctx.setTransform(ratio,0,0,ratio,0,0);ctx.clearRect(0,0,w,h);ctx.imageSmoothingEnabled=false;faces=[];const mode=$('mode-select').value,offset=model[2]?0:1,proj=(x,y,z)=>project(x,y,z,w,h);ctx.strokeStyle='#d6d8ca';ctx.lineWidth=1;for(let i=-3;i<=3;i++)for(const axis of [0,1]){const a=proj(axis?i:-3,-.5,axis?-3:i),b=proj(axis?i:3,-.5,axis?3:i);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke()}
for(const b of blocks){if(mode==='single'?b.y!==layer:b.y>layer)continue;const bm=window.TEA_BLOCK_MODELS[blockModelKey(b)],by=b.y*(mode==='explode'?1.65:1);for(const el of bm.elements){const [x1,y1,z1]=el.from,[x2,y2,z2]=el.to;const quads={north:[[x1,y2,z1],[x2,y2,z1],[x2,y1,z1],[x1,y1,z1]],south:[[x2,y2,z2],[x1,y2,z2],[x1,y1,z2],[x2,y1,z2]],west:[[x1,y2,z2],[x1,y2,z1],[x1,y1,z1],[x1,y1,z2]],east:[[x2,y2,z1],[x2,y2,z2],[x2,y1,z2],[x2,y1,z1]],up:[[x1,y2,z2],[x2,y2,z2],[x2,y2,z1],[x1,y2,z1]],down:[[x1,y1,z1],[x2,y1,z1],[x2,y1,z2],[x1,y1,z2]]};const defaults={north:[16-x2,16-y2,16-x1,16-y1],south:[x1,16-y2,x2,16-y1],west:[z1,16-y2,z2,16-y1],east:[16-z2,16-y2,16-z1,16-y1],up:[x1,z1,x2,z2],down:[x1,16-z2,x2,16-z1]};for(const [side,f]of Object.entries(el.faces)){const pts=quads[side].map(v=>{if(el.rotation)v=rot(v,el.rotation.axis,el.rotation.angle,el.rotation.origin);if(bm.x)v=rot(v,'x',-bm.x);if(bm.y)v=rot(v,'y',-bm.y);return proj(b.x+v[0]/16-.5,by+v[1]/16-.5,b.z-offset+v[2]/16-.5)});const cross=(pts[1].x-pts[0].x)*(pts[2].y-pts[0].y)-(pts[1].y-pts[0].y)*(pts[2].x-pts[0].x);if(cross<=.01)continue;faces.push({pts,b,side,texture:f.texture,uv:f.uv||defaults[side],rotation:f.rotation||0,depth:pts.reduce((a,v)=>a+v.depth,0)/4})}}}
faces.sort((a,b)=>b.depth-a.depth);for(const f of faces){const p=f.pts;ctx.save();ctx.beginPath();p.forEach((v,i)=>i?ctx.lineTo(v.x,v.y):ctx.moveTo(v.x,v.y));ctx.closePath();ctx.clip();const image=textureImages[f.texture];if(image?.complete&&image.naturalWidth){const corners=[...p];for(let n=0;n<f.rotation/90;n++)corners.unshift(corners.pop());const [a,b,,d]=corners;ctx.transform((b.x-a.x)/16,(b.y-a.y)/16,(d.x-a.x)/16,(d.y-a.y)/16,a.x,a.y);const uv=f.uv,unit=image.naturalWidth/16;ctx.drawImage(image,uv[0]*unit,uv[1]*unit,(uv[2]-uv[0])*unit,(uv[3]-uv[1])*unit,0,0,16,16)}else{ctx.fillStyle=materials[f.b.m][1];ctx.fillRect(0,0,w,h)}ctx.restore();ctx.save();ctx.beginPath();p.forEach((v,i)=>i?ctx.lineTo(v.x,v.y):ctx.moveTo(v.x,v.y));ctx.closePath();ctx.fillStyle=f.side==='up'?'#00000000':f.side==='north'||f.side==='south'?'#00000015':'#00000030';ctx.fill();if(f.b===selected||f.b.core){ctx.strokeStyle=f.b===selected?'#fff4a8':'#ffd36a';ctx.lineWidth=1.6;ctx.stroke()}ctx.restore()}
const front=proj(0,-.5,-offset-1);ctx.fillStyle='#3e5946';ctx.font='bold 15px sans-serif';ctx.textAlign='center';ctx.fillText('▼ 正面',front.x,front.y+15);if(loadedTextures<texturePaths.length&&!textureErrors){ctx.fillStyle='#3e5946';ctx.font='14px sans-serif';ctx.fillText('正在載入遊戲材質…',w/2,22)}}

canvas.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY};moved=false;canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>2)moved=true;yaw+=dx*.01;pitch=Math.max(.12,Math.min(1.45,pitch+dy*.008));drag={x:e.clientX,y:e.clientY};draw()});canvas.addEventListener('pointerup',e=>{drag=null;if(moved)return;const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;for(const f of [...faces].reverse()){ctx.beginPath();f.pts.forEach((v,i)=>i?ctx.lineTo(v.x,v.y):ctx.moveTo(v.x,v.y));ctx.closePath();const d=window.devicePixelRatio||1;if(ctx.isPointInPath(x*d,y*d)){inspect(f.b);break}}});canvas.addEventListener('pointercancel',()=>drag=null);canvas.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.65,Math.min(1.5,zoom-e.deltaY*.001));$('model-zoom').value=zoom*100;draw()},{passive:false});canvas.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();if(e.key==='ArrowLeft')yaw-=.2;if(e.key==='ArrowRight')yaw+=.2;if(e.key==='ArrowUp')pitch=Math.min(1.45,pitch+.1);if(e.key==='ArrowDown')pitch=Math.max(.12,pitch-.1);draw()}});$('structure-select').onchange=setup;$('layer-select').onchange=update;$('mode-select').onchange=draw;$('prev-layer').onclick=()=>{$('layer-select').value=layer-1;update()};$('next-layer').onclick=()=>{$('layer-select').value=layer+1;update()};$('rotate-left').onclick=()=>{yaw-=Math.PI/4;draw()};$('rotate-right').onclick=()=>{yaw+=Math.PI/4;draw()};$('view-top').onclick=()=>{yaw=0;pitch=1.45;draw()};$('reset-view').onclick=()=>{yaw=-.6;pitch=.5;zoom=1;$('model-zoom').value=100;draw()};$('model-zoom').oninput=e=>{zoom=+e.target.value/100;draw()};new ResizeObserver(draw).observe(canvas);setup();
